from griffe import Extension, load

class AppendCheckedExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_package_members_collected(self, package, members):
        self._append_to_functions(members)

    def on_module_members_collected(self, module, members):
        self._append_to_functions(members)

    def on_class_members_collected(self, class_, members):
        self._append_to_functions(members)

    def _append_to_functions(self, members):
        for member in members.values():
            if member.is_function:
                if member.docstring:
                    member.docstring.value += " [checked]"

# Load the package with the extension
module = load("mypkg", extensions=[AppendCheckedExtension()])
print(module)
